import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261023-head-separate-comparison',site=stage+'/website',a=json(stage+'/TEST_ADAPTERS.json');
function hunk(text,from,to){const offset=text.indexOf(from);assert(offset>=0);const start=text.lastIndexOf('\n',offset)+1,end=text.indexOf('\n',offset+from.length),old=text.slice(start,end<0?text.length:end).replace(/\r$/,'');assert(old.includes(from));const next=old.replace(from,to);return '@@\n-'+old+'\n'+next.split('\n').map(l=>'+'+l).join('\n')+'\n';}
const patch='*** Begin Patch\n'+a.edits.map(r=>{const text=fs.readFileSync(site+'/'+r.path,'utf8');assert.equal(hash(site+'/'+r.path),r.beforeSha256,'Original failed patch was atomic');return '*** Update File: '+site+'/'+r.path+'\n'+hunk(text,r.old,r.next)+(r.second?hunk(text,r.second.old,r.second.next):'');}).join('')+'*** End Patch';fs.writeFileSync(stage+'/TEST_ADAPTER_PATCH_V2.json',JSON.stringify({at:new Date().toISOString(),originalPatchRejectedBeforeSourceWrite:true,reason:'Substring seam was emitted as a complete-line patch; use exact full source lines without broadening the edits.',patch},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({patch:stage+'/TEST_ADAPTER_PATCH_V2.json'}));
